// 1) build W1..W3 with local odd version
w1.store(payload1, Ordering::Relaxed);
w2.store(payload2, Ordering::Relaxed);
w3.store(with_tail_ver(payload3, odd_ver), Ordering::Relaxed);

// 2) publish head with even version
let head = pack_head(/*commit=1, ver=odd_ver+1, ...*/);
w0.store(head, Ordering::Release);

reader-one-decision.code:
let h = w0.load(Ordering::Relaxed);
if !is_committed_even(h) { return Deny; }
let t = w3.load(Ordering::Relaxed);
if !head_tail_match(h, t) { return Deny; }
Decide::YesOrNo(decode_and_branch(h, t))

minimal-capsule.code:
#[repr(C, align(64))]
pub struct Capsule128 {
    head: AtomicU128, // commit:1 | ver:8 | ... (header)
    body: AtomicU128, // payload + ver_tail:8
}

impl Capsule128 {
    pub fn publish(&self, payload: u128, odd_ver: u8) {
        let body = set_ver_tail(payload, odd_ver);
        self.body.store(body, Ordering::Relaxed);
        let head = make_head(/*commit=1, ver=odd_ver+1 even, ...*/);
        self.head.store(head, Ordering::Release);
    }
    pub fn read_ok(&self) -> Option<(u128,u128)> {
        let h = self.head.load(Ordering::Relaxed);
        if !is_committed_even(h) { return None; }
        let b = self.body.load(Ordering::Relaxed);
        if !head_tail_match(h, b) { return None; }
        Some((h, b))
    }
}
